import{_ as n,C as e,c as r,o,aj as s,G as t,w as u}from"./chunks/framework.Bfdr4H5E.js";const y=JSON.parse('{"title":"Routines – Pre-Session","description":"","frontmatter":{"outline":"deep","prev":{"text":"Trading Plan Summary Details","link":"/trading-with-pav/trading-plan-summary-details"},"next":{"text":"Routines – During Session","link":"/trading-with-pav/routines-during-session"}},"headers":[],"relativePath":"trading-with-pav/routines-pre-session.md","filePath":"trading-with-pav/routines-pre-session.md"}'),c={name:"trading-with-pav/routines-pre-session.md"};function h(d,i,p,f,m,g){const l=e("GraphComment"),a=e("ClientOnly");return o(),r("div",null,[i[0]||(i[0]=s('<h1 id="routines-–-pre-session" tabindex="-1">Routines – Pre-Session <a class="header-anchor" href="#routines-–-pre-session" aria-label="Permalink to &quot;Routines – Pre-Session&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#routines-–-pre-session-1">Routines – Pre-Session</a><ul><li><a href="#personal-preparation">Personal Preparation</a></li><li><a href="#trading-preparation">Trading Preparation</a></li><li><a href="#initial-analysis">Initial Analysis</a></li><li><a href="#final-preparation">Final Preparation</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="routines-–-pre-session-1" tabindex="-1">Routines – Pre-Session <a class="header-anchor" href="#routines-–-pre-session-1" aria-label="Permalink to &quot;Routines – Pre-Session&quot;">​</a></h2><h3 id="personal-preparation" tabindex="-1">Personal Preparation <a class="header-anchor" href="#personal-preparation" aria-label="Permalink to &quot;Personal Preparation&quot;">​</a></h3><ul><li><ol><li>Initial Check of Physical and Mental Health</li></ol><ul><li>a) If suffering from any ill health or stress, consider the need for cancelling the session, reducing the session, reducing position sizes, or implementing periodic checks of myself and my performance.</li><li>b) Seek independent opinion from <strong>__________</strong>.</li></ul></li><li><ol start="2"><li>Physical</li></ol><ul><li>a) Ensure sufficient sleep, in accordance with the 5/12 fatigue management plan.</li><li>b) Ensure sufficient and healthy food intake (sufficient to last till first break)</li><li>c) Fill water bottle and place at trading desk</li><li>d) Conduct a relaxation and breathing session</li></ul></li><li><ol start="3"><li>Psychological</li></ol><ul><li>a) Review Motivational Journal</li></ul></li></ul><h3 id="trading-preparation" tabindex="-1">Trading Preparation <a class="header-anchor" href="#trading-preparation" aria-label="Permalink to &quot;Trading Preparation&quot;">​</a></h3><ul><li><ol><li>Platform &amp; Computer Preparation – Part 1</li></ol><ul><li>a) Virus check, clean &amp; restart computer</li><li>b) Open platform with sim account</li></ul></li><li><ol start="2"><li>Review the previous session.</li></ol><ul><li>a) Trading Journal &amp; Log</li><li>b) Lessons learnt (from previous session Log)</li><li>c) Sim trade (market replay) any key sequences from previous session</li><li>d) Sim trade – execution drills</li><li>e) Goals recommended for today</li><li>f) Close sim account.</li></ul></li><li><ol start="3"><li>Prepare today’s Trading Journal and Log</li></ol><ul><li>a) Market <ul><li>i) Confirm no contract rollover (next date due: <strong>________</strong>)</li></ul></li><li>b) Session timings</li><li>c) Balance &amp; position sizes</li><li>d) Review Economic Reports</li><li>e) Record daily goals</li></ul></li><li><ol start="4"><li>Platform &amp; Computer Preparation – Part 2</li></ol><ul><li>a) Open platform with live account</li><li>b) Synchronize system clock</li><li>c) Set alarms for prior to session start, or any potentially volatile news event I wish to watch prior to session start</li><li>d) Set my candle timer</li><li>e) Confirm order entry / DOM screen is correctly configured – contract, position sizes, order strategy (stop, limit parameters) and one-click order entry</li></ul></li></ul><h3 id="initial-analysis" tabindex="-1">Initial Analysis <a class="header-anchor" href="#initial-analysis" aria-label="Permalink to &quot;Initial Analysis&quot;">​</a></h3><ul><li><ol><li>Define Structure</li></ol><ul><li>a) Define a structural framework within which our trading timeframe price action will move. <ul><li>i) Identify areas of Support or Resistance on the higher timeframe (30 min) chart based on swing highs and lows.</li></ul></li></ul></li><li><ol start="2"><li>Define Trend</li></ol><ul><li>a) Assess the movement of past price action within our market structure framework. <ul><li>i) Identify significant swing highs and lows on the trading timeframe (3 min) chart.</li><li>ii) Identify the trend direction – up, down or sideways</li></ul></li></ul></li><li><ol start="3"><li>Identify Strength &amp; Weakness</li></ol><ul><li>a) Analyze price movement within the trend to identify signs of strength or weakness. <ul><li>i) Analyze momentum of recent price swings <ul><li>(1) Compare the momentum of the current price swing with the momentum of the previous price swing in the same direction? Is price faster or slower than before? What does that mean?</li><li>(2) Compare the momentum of the current price swing with the momentum of the previous price swing in the opposite direction? Is price faster or slower than before? What does that mean?</li><li>(3) Is the current price accelerating or decelerating? What does that mean?</li></ul></li><li>ii) Compare projection and depth of recent price swings <ul><li>(1) Increased projection is a sign of potential trend strength. Decreased projection is a sign of potential trend weakness.</li><li>(2) Increased depth is a sign of potential trend weakness. Decreased depth is a sign of potential trend strength.</li></ul></li><li>iii) Identify signs of failure to continue (i.e. failure to meet expectations). <ul><li>(1) Failure to continue is a sign of weakness</li></ul></li><li>iv) Identify signs of strength or weakness via any miscellaneous methods <ul><li>(1) Volume analysis</li><li>(2) Market Internal indicators</li></ul></li></ul></li></ul></li><li><ol start="4"><li>Identify Future Trend Direction</li></ol><ul><li>a) What is the likely path of future price action? Determine the likely path of future price action, in accordance with the six principles listed below.</li></ul></li></ul><div class="warning custom-block"><p class="custom-block-title">Six Principles of Future Trend Direction:</p><p>Within the S/R framework:</p><ul><li><strong>First Principle</strong> – We expect an up or down trend to continue in its current state until the next S/R barrier, unless displaying evidence of weakness within the trend.</li><li><strong>Second Principle</strong> – When an up or down trend shows evidence of weakness, we expect a higher likelihood of a complex correction rather than a reversal, until such time as the market shows both price acceptance and strength in the new trend direction.</li><li><strong>Third Principle</strong> – A sideways trend within the framework is expected to continue in its current state, unless displaying evidence of strength towards the range boundary.</li><li><strong>Fourth Principle</strong> – When a sideways trend shows evidence of strength towards the range boundary, we expect a break of the boundary. We observe the behavior of price post-breakout for clues as to future direction: <ul><li>Weakness following the breakout – the expectation is for a breakout failure and reversal back within the trading range.</li><li>Weakness on the pullback – the expectation is for a breakout pullback and continuation.</li></ul></li></ul><p>At the edges of the S/R framework:</p><ul><li><strong>Fifth Principle</strong> – We expect a test of our framework S/R to hold, unless strength is displayed on approach to the S/R boundary.</li><li><strong>Sixth Principle</strong> – If strength is shown on an approach to an S/R barrier, we expect a breakout and watch the behavior of price post-breakout for clues as to future direction: <ul><li>Weakness following the breakout – the expectation is for a breakout failure and reversal back through the area of S/R.</li><li>Weakness on the pullback – the expectation is for a breakout pullback and continuation.</li></ul></li></ul></div><ul><li><ol start="5"><li>Visualize Future Price Action</li></ol><ul><li>a) How do you expect price to behave? Visualize the future price action, based upon your expectations for future trend direction and its interaction with the market structure S/R levels. <ul><li>i) What price action would validate your assessment of future trend direction?</li><li>ii) What price action would invalidate your assessment of future trend direction?</li></ul></li></ul></li><li><ol start="6"><li>Identify Areas of Trade Opportunity</li></ol><ul><li>a) Based upon your expectations for future trend direction and how it should interact with areas of S/R and swing highs / lows, identify the next potential setup areas.</li><li>b) Areas of trade opportunity are found where weakness plays out against S/R and swing highs / lows (TST, BOF, BPB), or within a trend (PB, CPB).</li></ul></li><li>Steady trend environment: <ul><li>Higher Probability</li><li>PB and CPB</li></ul></li><li>Weakening trend environment <ul><li>Higher Probability <ul><li>CPB</li><li>PB if they break a previous swing low (uptrend) or swing high (downtrend)</li></ul></li><li>Lower Probability <ul><li>Any other PB</li><li>Counter-trend TST or BOF of swing high (uptrend) or swing low (downtrend)</li></ul></li></ul></li><li>Within a Sideways Trading Range with a clear intra-range trend <ul><li>Lower Probability <ul><li>PB and CPB</li></ul></li></ul></li><li>Approaching higher timeframe S/R or range S/R, with no sign of potential breakout <ul><li>Higher Probability <ul><li>TST</li></ul></li></ul></li><li>Approaching higher timeframe S/R or range S/R, with strength showing signs of potential breakout <ul><li>Higher Probability <ul><li>BOF or BPB</li></ul></li></ul></li></ul><h3 id="final-preparation" tabindex="-1">Final Preparation <a class="header-anchor" href="#final-preparation" aria-label="Permalink to &quot;Final Preparation&quot;">​</a></h3><ul><li><ol><li>Final Confirmation Check</li></ol><ul><li>a) Again confirm my physical and mental health.</li><li>b) If suffering from any ill health or stress, consider the need for cancelling the session, reducing the session, reducing position sizes, or implementing periodic checks of myself and my performance.</li><li>c) Confirm again that my fatigue levels are within the limits as defined by the 5/12 fatigue management plan. No trading is to occur if I am classified as suffering from fatigue.</li></ul></li><li><ol start="2"><li>Final relaxation and breathing session</li></ol></li></ul><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',14)),t(a,null,{default:u(()=>[t(l)]),_:1})])}const b=n(c,[["render",h]]);export{y as __pageData,b as default};
